  /* C428 (A52) : second paquet : ses phrases rejoignent le dictionnaire du moteur déjà installé, qui retraduit l'écran. */
  if (dejaLa) { try { if (w.VerdictLanguesComplements && typeof w.VerdictLanguesComplements.ajouter === 'function') w.VerdictLanguesComplements.ajouter(D); } catch (e) {} return; }
  function fusionner(Dn) { Object.keys(Dn || {}).forEach(function (k) { var r = D[k] || (D[k] = ['', '', '', '', '', '']), n = Dn[k] || []; for (var i = 0; i < 6; i++) if (n[i]) r[i] = n[i]; }); }

  /* ── Normalisation identique au moteur de Pilotage (trNorm) ── */
  function norm(x) { return String(x == null ? '' : x).replace(/[   ]/g, ' ').replace(/\s+([:;!?%])/g, ' $1').replace(/[ \t]+/g, ' '); }

